def merge_usage(*usages: dict[str, Any] | None) -> dict[str, Any]:
    """Sum several calls (for example a generator plus its judge)."""
    merged = {
        "prompt_tokens": 0,
        "completion_tokens": 0,
        "reasoning_tokens": 0,
        "cached_tokens": 0,
        "cache_write_tokens": 0,
        "total_tokens": 0,
    }
    for usage in usages:
        if not usage:
            continue
        for key in merged:
            merged[key] += _int(usage.get(key))
    merged["cache_hit_rate"] = (
        round(merged["cached_tokens"] / merged["prompt_tokens"], 4)
        if merged["prompt_tokens"]
        else 0.0
    )
    merged["total_tokens"] = (
        merged["prompt_tokens"]
        + merged["completion_tokens"]
        + merged["reasoning_tokens"]
    )
    return merged

